export interface LegacyOrderDto { order_id: string; sku: string; qty: number }
export interface OrderDto { id: string; sku: string; quantity: number }

export function toCanonical(w: LegacyOrderDto): OrderDto {
  if (!Number.isInteger(w.qty) || w.qty <= 0) throw new InvalidMessage('qty');
  return { id: w.order_id, sku: w.sku.trim().toUpperCase(), quantity: w.qty };
}

import { z } from 'zod';

export const LegacyOrderSchema = z.object({
  order_id: z.string().min(1),
  sku: z.string().transform(s => s.trim().toUpperCase()),
  qty: z.number().int().positive(),
}).transform(({ order_id, sku, qty }) => ({ id: order_id, sku, quantity: qty }));

export type OrderDto = z.infer<typeof LegacyOrderSchema>;   // { id, sku, quantity }

